\set ON_ERROR_STOP on
do $$declare n int;begin
 select count(*)into n from pg_class c join pg_namespace s on s.oid=c.relnamespace where s.nspname='public'and c.relname in('e10_unique_item_facet_decisions','e10_market_observation_fact_decisions','e10_market_observation_equivalence_decisions','e10_market_observation_coverage_decisions')and c.relrowsecurity;
 if n<>4 then raise exception'evidence RLS count %',n;end if;
 if exists(select 1 from information_schema.role_table_grants where table_schema='public'and table_name like'e10%decisions'and grantee in('anon','authenticated'))then raise exception'evidence client grant leak';end if;
end $$;
begin;
do $$
declare o uuid:=gen_random_uuid();o2 uuid:=gen_random_uuid();r uuid:=gen_random_uuid();v uuid:=gen_random_uuid();p uuid:=gen_random_uuid();p2 uuid:=gen_random_uuid();u uuid:=gen_random_uuid();u2 uuid:=gen_random_uuid();a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();c uuid:=gen_random_uuid();d uuid:=gen_random_uuid();e uuid:=gen_random_uuid();f uuid:=gen_random_uuid();g uuid:=gen_random_uuid();h uuid:=gen_random_uuid();j uuid:=gen_random_uuid();k uuid:=gen_random_uuid();dk uuid:=gen_random_uuid();ek uuid:=gen_random_uuid();ck uuid:=gen_random_uuid();fact_key uuid:=gen_random_uuid();e1 uuid;cv1 uuid;fact1 uuid;fp1 text;fp2 text;rev0 bigint;rev2 bigint;chain_ids uuid[]:=array[]::uuid[];tail_ids uuid[]:=array[]::uuid[];i integer;
begin
