 insert into public.e10_catalog_releases(id,release_name)values(r,'X7d');insert into public.e10_players(id,name)values(p,'Subject'),(p2,'Foreign');insert into public.e10_catalog_variants(id,release_id)values(v,r);insert into public.e10_catalog_variant_subjects(variant_id,player_id)values(v,p);insert into public.e10_unique_items(id,organization_id,catalog_variant_id,item_kind)values(u,o,v,'card'),(u2,o,v,'card');
 set local session_replication_role=replica;
 insert into public.e10_market_observations(id,organization_id,observation_kind,catalog_variant_id,occurred_at,currency,amount,quantity,source_kind,raw_payload_snapshot)values(a,o,'completed_sale',v,'2026-01-01','USD',500,5,'manual','{}'),(b,o,'completed_sale',v,'2026-01-01','USD',500,5,'csv','{}'),(c,o2,'completed_sale',v,'2026-01-01','USD',500,5,'manual','{}'),(d,o,'completed_sale',v,'2026-01-02','USD',500,5,'manual','{}'),(e,o,'completed_sale',v,'2026-01-02','USD',500,5,'csv','{}'),(f,o,'completed_sale',v,'2026-01-03','USD',25,null,'manual','{}'),(g,o,'completed_sale',v,'2026-01-04','USD',25,null,'manual','{}'),(h,o,'completed_sale',v,'2026-01-06','USD',25,null,'manual','{}'),(j,o,'completed_sale',v,'2026-01-07','USD',500,5,'manual','{}'),(k,o,'completed_sale',v,'2026-01-08','USD',25,null,'manual','{}');
 for i in 1..34 loop chain_ids:=array_append(chain_ids,gen_random_uuid());tail_ids:=array_append(tail_ids,gen_random_uuid());insert into public.e10_market_observations(id,organization_id,observation_kind,catalog_variant_id,occurred_at,currency,amount,quantity,source_kind,raw_payload_snapshot)values(chain_ids[i],o,'asking_price',v,'2026-01-05','USD',10,1,'manual','{}'),(tail_ids[i],o,'asking_price',v,'2026-01-09','USD',10,1,'manual','{}');end loop;
