 insert into public.e10_market_observation_fact_decisions(organization_id,decision_key,observation_id,revision,action,transaction_quantity,reason,evidence,idempotency_key,request_fingerprint)values(o,gen_random_uuid(),g,1,'assert',2,'x','{}','fact-quantity-only','fp');
 begin insert into public.e10_market_observation_fact_decisions(organization_id,decision_key,observation_id,revision,action,condition_state,reason,evidence,idempotency_key,request_fingerprint)values(o,gen_random_uuid(),h,1,'assert','graded','x','{}','fact-graded-missing-labels','fp');raise exception'graded fact without grader/grade accepted';exception when check_violation then null;end;
 begin insert into public.e10_market_observation_fact_decisions(organization_id,decision_key,observation_id,revision,action,grader_code,grade_label,transaction_quantity,reason,evidence,idempotency_key,request_fingerprint)values(o,gen_random_uuid(),k,1,'assert','PSA','10',1,'x','{}','fact-null-condition-graded','fp');raise exception'NULL condition with grade fields accepted';exception when check_violation then null;end;
