 begin insert into public.e10_market_observation_equivalence_decisions(organization_id,decision_key,duplicate_observation_id,canonical_observation_id,revision,action,duplicate_fingerprint,canonical_fingerprint,reason,evidence,idempotency_key,request_fingerprint)values(o,gen_random_uuid(),a,c,1,'link',fp1,e10.market_observation_fingerprint(o2,c),'x','{}','eq-cross-org','fp');raise exception'cross-org equivalence accepted';exception when check_violation then null;end;

