 insert into public.e10_market_observation_fact_decisions(organization_id,decision_key,observation_id,revision,action,condition_state,transaction_quantity,amount_basis,reviewed_unit_amount,supersedes_decision_id,reason,evidence,idempotency_key,request_fingerprint)values(o,fact_key,a,2,'assert','raw',5,'unit_price',500,fact1,'corrected','{}','fact1-correction','fp');
