 if not exists(select 1 from public.e10_current_market_observation_coverage where organization_id=o and decision_key=ck and coverage_status='partial')then raise exception'coverage terminal wrong';end if;if(select revision from public.e10_market_org_revisions where organization_id=o)<=rev0 then raise exception'org revision did not advance';end if;if(select revision from public.e10_market_org_revisions where organization_id=o2)<>rev2 then raise exception'foreign org revision advanced';end if;
